choose.when:
AND (
  status = 'expired'
  OR (
    expires_at IS NOT NULL
    AND expires_at <= #{now}
    AND status NOT IN ('connected', 'rejected', 'revoked', 'cleaning', 'cleanup_failed')
  )
)

choose.otherwise:
AND status = #{status}
AND NOT (
  expires_at IS NOT NULL
  AND expires_at <= #{now}
  AND status NOT IN ('connected', 'rejected', 'revoked', 'expired', 'cleaning', 'cleanup_failed')
)

mapper.select:
SELECT *
FROM wechat_bind_links

ORDER BY created_at DESC, token ASC
LIMIT #{pageSize}
OFFSET #{offset}
